## Why This Is Asked
This question tests mastery of persistent data structures, real-world versioning systems, and memory-time trade-offs. It also probes understanding of shared nodes and functional update semantics.

## Key Concepts
- Fully persistent data structures via path-copying
- Implicit treap or segment tree with augmented sums and sizes
- Version management with O(log n) mutations per update
- Correct boundary handling for empty intervals and edge operations

## Code Example
```javascript
class Node {
  constructor(val, prio, left = null, right = null) {
    this.val = val;
    this.prio = prio;
    this.left = left;
    this.right = right;
    this.size = 1;
    this.sum = val;
  }

  update() {
    this.size = 1 + (this.left?.size ?? 0) + (this.right?.size ?? 0);
    this.sum = this.val + (this.left?.sum ?? 0) + (this.right?.sum ?? 0);
  }
}

function split(root, k) {
  if (!root) return [null, null];
  const leftSize = root.left?.size ?? 0;
  if (k <= leftSize) {
    const [l, r] = split(root.left, k);
    root.left = r;
    root.update();
    return [l, root];
  } else {
    const [l, r] = split(root.right, k - leftSize - 1);
    root.right = l;
    root.update();
    return [root, r];
  }
}

function merge(left, right) {
  if (!left || !right) return left ?? right;
  if (left.prio < right.prio) {
    left.right = merge(left.right, right);
    left.update();
    return left;
  } else {
    right.left = merge(left, right.left);
    right.update();
    return right;
  }
}

function rangeSum(root, l, r) {
  const [, mid] = split(root, l);
  const [target, rest] = split(mid, r - l + 1);
  const result = target?.sum ?? 0;
  return merge(merge(null, target), rest);
}

function insertAt(root, index, val) {
  const [left, right] = split(root, index);
  const newNode = new Node(val, Math.random());
  return merge(merge(left, newNode), right);
}

function eraseAt(root, index) {
  const [left, mid] = split(root, index);
  const [, right] = split(mid, 1);
  return merge(left, right);
}
```

## Why This Is Asked
Tests ability to design a compact, eviction-aware data structure for time-windowed counting, a common pattern in real-time analytics.

## Key Concepts
- Sliding window eviction via timestamped events
- Bucketed counts: map from count to set of users for fast top-k
- Invariants: update counts atomically during insertion and eviction
- Complexity: O(log n) updates, O(k log n) top-k retrieval

## Code Example
```javascript
class WindowCounter {
  constructor(W) {
    this.W = W;
    this.count = new Map(); // user -> cnt
    this.buckets = new Map(); // cnt -> Set<user>
    this.events = new Deque(); // (ts, user)
  }
  _addToBucket(cnt, user) {
    if (!this.buckets.has(cnt)) this.buckets.set(cnt, new Set());
    this.buckets.get(cnt).add(user);
  }
  _removeFromBucket(cnt, user) {
    if (!this.buckets.has(cnt)) return;
    this.buckets.get(cnt).delete(user);
    if (this.buckets.get(cnt).size === 0) this.buckets.delete(cnt);
  }
  prune(now) {
    while (this.events.length && this.events.peek().ts <= now - this.W) {
      const {ts, user} = this.events.shift();
      const c = this.count.get(user) || 0;
      if (c > 0) {
        this._removeFromBucket(c, user);
        const nc = c - 1;
        if (nc > 0) {
          this._addToBucket(nc, user);
          this.count.set(user, nc);
        } else {
          this.count.delete(user);
        }
      }
    }
  }
  addEvent(user, ts) {
    this.events.push({ts, user});
    this.prune(ts);
    const c = this.count.get(user) || 0;
    if (c > 0) this._removeFromBucket(c, user);
    const nc = c + 1;
    this._addToBucket(nc, user);
    this.count.set(user, nc);
  }
  topK(now, k) {
    const res = [];
    // iterate counts from high to low
    const counts = Array.from(this.buckets.keys()).sort((a,b)=>b-a);
    for (const cnt of counts) {
      const set = this.buckets.get(cnt);
      const users = Array.from(set).sort((a,b)=>a-b); // tie-breaker by userId
      for (const u of users) {
        res.push([u, cnt]);
        if (res.length === k) return res;
      }
    }
    return res;
  }
}
```

## Follow-up Questions
- How would you adapt this to support multiple simultaneous windows (e.g., W1 and W2) efficiently?
- How would you handle very large userId spaces with memory constraints, or concurrent updates in a multi-threaded environment?

